function startGame(mode) {
  gameMode = mode;
  document.getElementById('menu').style.display = 'none';
  document.getElementById('gameOver').style.display = 'none';
  document.getElementById('gameContainer').style.display = 'flex';

  initGame();
}

function initGame() {
  // Snake 1 starts left side going right
  snake1 = [{x:5, y:15}, {x:4, y:15}, {x:3, y:15}];
  dir1 = DIR.RIGHT;

  // Snake 2 starts right side going left
  snake2 = [{x:24, y:15}, {x:25, y:15}, {x:26, y:15}];
  dir2 = DIR.LEFT;

  score1 = 0;
  score2 = 0;
  gameRunning = true;
  accumulator = 0;
  lastTime = 0;

  placeFood();
  updateScoreboard();
  requestAnimationFrame(gameLoop);
}

function placeFood() {
  let pos;
  do {
    pos = { x: Math.floor(Math.random() * GRID), y: Math.floor(Math.random() * GRID) };
  } while (isOccupied(pos.x, pos.y));
  food = pos;
}

function isOccupied(x, y) {
  for (let s of snake1) if (s.x === x && s.y === y) return true;
  for (let s of snake2) if (s.x === x && s.y === y) return true;
  return false;
}

function isWall(x, y) {
  return x < 0 || x >= GRID || y < 0 || y >= GRID;
}

function isSelf(x, y, snake) {
  for (let i = 0; i < snake.length; i++) if (snake[i].x === x && snake[i].y === y) return true;
  return false;
}

function isCollision(x, y) {
  if (isWall(x, y)) return true;
  if (isSelf(x, y, snake1)) return true;
  if (isSelf(x, y, snake2)) return true;
  return false;
}

function updateScoreboard() {
  document.getElementById('scoreP1').textContent = `Player 1: ${score1}`;
  document.getElementById('scoreP2').textContent = `Player 2: ${score2}`;
}

function getCPUDir(snake, target) {
  const head = snake[0];
  const moves = [DIR.UP, DIR.DOWN, DIR.LEFT, DIR.RIGHT];

  // Filter out moves that would cause collision
  const safeMoves = moves.filter(m => {
    const nx = head.x + m.x;
    const ny = head.y + m.y;
    return !isCollision(nx, ny);
  });

  if (safeMoves.length === 0) return moves[0]; // sacrifice

  // Score each safe move by distance to food
  let bestMove = safeMoves[0];
  let bestDist = Infinity;

  for (let m of safeMoves) {
    const nx = head.x + m.x;
    const ny = head.y + m.y;
    const dist = Math.abs(nx - target.x) + Math.abs(ny - target.y);
    if (dist < bestDist) {
      bestDist = dist;
      bestMove = m;
    }
  }

  return bestMove;
}

function getCPUTarget() {
