  document.getElementById('gameContainer').style.display = 'none';
  gameOverDiv.style.display = 'block';
}

function draw() {
  ctx.fillStyle = '#0a0a0a';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Grid lines (subtle)
  ctx.strokeStyle = '#151515';
  ctx.lineWidth = 0.5;
