    const alpha = 1 - (i / snake1.length) * 0.5;
    ctx.fillStyle = i === 0 ? '#4af' : `rgba(68, 170, 255, ${alpha})`;
    ctx.fillRect(s.x * CELL + 1, s.y * CELL + 1, CELL - 2, CELL - 2);
  }

  // Snake 2
  for (let i = 0; i < snake2.length; i++) {
